const STATE = require('STATE')
const statedb = STATE(__filename)
const { sdb, get } = statedb(fallback_module)

require('input_field')
require('button')

module.exports = wallet_setup

async function wallet_setup(opts = {}, protocol) {
  const { sdb } = await get(opts.sid)
  const { drive } = sdb
  const on = { style: inject, data: ondata, icons: onicons }

  const el = document.createElement('div')
  const shadow = el.attachShadow({ mode: 'closed' })

  shadow.innerHTML = `
    <div class="wallet-setup">
      <section class="setup-home" data-view="home">
        <header class="page-header">
          <p class="eyebrow">Security & recovery</p>
          <h1>Wallet Setup</h1>
          <p class="page-copy">Create, restore, or safely close your Lightning wallet.</p>
        </header>

        <div class="current-wallet">
          <span class="status-dot"></span>
          <div>
            <span class="card-caption">Current wallet</span>
            <strong class="current-wallet-alias">Loading wallet alias…</strong>
          </div>
        </div>

        <div class="setup-options">
          <button class="option-card" data-action="open-create">
            <span class="option-icon new-wallet-icon">+</span>
            <span class="option-content">
              <strong>Create New Wallet</strong>
              <small>Generate a new node identity and recovery phrase.</small>
            </span>
            <span class="chevron">›</span>
          </button>

          <button class="option-card inactive-option">
            <span class="option-icon import-icon">↓</span>
            <span class="option-content">
              <strong>Import Existing Wallet</strong>
              <small>Restore with a mnemonic and channel backup.</small>
            </span>
          </button>

          <button class="option-card danger-card inactive-option">
            <span class="option-icon drain-icon">!</span>
            <span class="option-content">
              <strong>Emergency Drain</strong>
              <small>Close channels and sweep funds to a safe address.</small>
            </span>
          </button>
        </div>
      </section>

      <section class="create-view hidden" data-view="create">
        <header class="subpage-header">
          <button class="back-button" data-action="back" aria-label="Back to Wallet Setup">←</button>
          <div>
            <p class="eyebrow">Wallet Setup</p>
            <h1>Create New Wallet</h1>
          </div>
        </header>

        <div class="warning-card">
          <span class="warning-icon">!</span>
          <div>
            <strong>This replaces your current wallet</strong>
            <p>Your current Node 4 data and identity will be removed. Save its channel backup before continuing.</p>
          </div>
        </div>

        <div class="backup-card">
          <div class="section-heading">
            <div>
              <span class="step-label">Recommended first</span>
              <h2>Back up current channels</h2>
            </div>
            <span class="file-badge">SCB</span>
          </div>
          <p>Download the latest Static Channel Backup. If this wallet has no channels yet, no SCB file will exist.</p>
          <button class="secondary-button" data-action="download-scb">
            <span>↓</span> Download SCB backup
          </button>
          <div class="inline-status hidden scb-status" role="status"></div>
        </div>

        <div class="mnemonic-card create-mnemonic-card">
          <div class="section-heading">
            <div>
              <span class="step-label">Secret recovery phrase</span>
              <h2>Your 12-word mnemonic</h2>
            </div>
            <span class="secret-badge">Private</span>
          </div>
          <p class="mnemonic-warning mnemonic-help">Your recovery words will appear here as soon as the new wallet is created.</p>
          <textarea class="mnemonic-text create-mnemonic-text" readonly placeholder="Loading saved recovery phrase…"></textarea>
          <div class="button-row">
            <button class="secondary-button mnemonic-action" data-action="copy-mnemonic" disabled>Copy phrase</button>
            <button class="secondary-button mnemonic-action" data-action="download-mnemonic" disabled>Save phrase</button>
          </div>
          <div class="inline-status hidden create-copy-status" role="status"></div>
        </div>

        <div class="detail-card created-node-card hidden">
          <span class="detail-label">New node ID</span>
          <div class="detail-value node-id-value"></div>
          <button class="text-button" data-action="copy-node-id">Copy node ID</button>
        </div>

        <label class="confirmation-row">
          <input type="checkbox" class="create-confirmation">
          <span>I understand this will permanently replace the current wallet and I have saved the recovery information I need.</span>
        </label>

        <button class="primary-button create-button" data-action="create-wallet" disabled>Create new wallet</button>
        <div class="notice hidden create-status" role="status"></div>
      </section>

      <section class="success-view hidden" data-view="success">
        <header class="success-header">
          <span class="success-mark">✓</span>
          <p class="eyebrow">Wallet ready</p>
          <h1>New wallet created</h1>
          <p>Your Lightning node restarted with a new identity.</p>
        </header>

        <div class="detail-card">
          <span class="detail-label">Node ID</span>
          <div class="detail-value node-id-value"></div>
          <button class="text-button" data-action="copy-node-id">Copy node ID</button>
        </div>

        <div class="mnemonic-card">
          <div class="section-heading">
            <div>
              <span class="step-label">Secret recovery phrase</span>
              <h2>Save these 12 words</h2>
            </div>
            <span class="secret-badge">Private</span>
          </div>
          <p class="mnemonic-warning">Anyone with these words can control this wallet. Store them offline and never share them.</p>
          <textarea class="mnemonic-text" readonly></textarea>
          <div class="button-row">
            <button class="secondary-button" data-action="copy-mnemonic">Copy phrase</button>
            <button class="secondary-button" data-action="download-mnemonic">Save phrase</button>
          </div>
          <div class="inline-status hidden copy-status" role="status"></div>
        </div>

        <div class="backup-card new-backup-card">
          <div class="section-heading">
            <div>
              <span class="step-label">Lightning recovery</span>
              <h2>Channel backup</h2>
            </div>
            <span class="file-badge">SCB</span>
          </div>
          <p>Download a fresh backup after opening channels. A new wallet without channels does not have an SCB yet.</p>
          <button class="secondary-button" data-action="download-scb">
            <span>↓</span> Download current SCB
          </button>
          <div class="inline-status hidden success-scb-status" role="status"></div>
        </div>

        <button class="primary-button" data-action="finish">Done</button>
      </section>
    </div>
    <style></style>
  `

  const style = shadow.querySelector('style')
  const sendUp = protocol ? protocol(receiveFromParent) : null
  let currentMnemonic = ''
  let currentNodeId = ''
  let scbStatusTarget = null
  let walletCreated = false

  await sdb.watch(onbatch)

  shadow.addEventListener('click', handleClick)
  shadow.querySelector('.create-confirmation').addEventListener('change', function (event) {
    shadow.querySelector('.create-button').disabled = !event.target.checked
  })

  el.open = function () {
    resetCreateView()
    showView('home')
    request({ type: 'get_wallet_setup_details' })
  }

  request({ type: 'get_wallet_setup_details' })

  return el

  async function handleClick(event) {
    const target = event.target.closest('[data-action]')
    if (!target) return

    const action = target.dataset.action
    if (action === 'open-create') {
      resetCreateView()
      showView('create')
      request({ type: 'get_wallet_recovery_phrase' })
    }
    if (action === 'back' || action === 'finish') {
      resetCreateView()
      showView('home')
      request({ type: 'get_wallet_setup_details' })
    }
    if (action === 'download-scb') {
      scbStatusTarget = target.closest('.backup-card').querySelector('.inline-status')
      setButtonLoading(target, true, 'Requesting backup…')
      request({ type: 'export_wallet_scb' })
    }
    if (action === 'create-wallet') createWallet(target)
    if (action === 'copy-mnemonic') {
      const copied = await copyText(currentMnemonic)
      showMnemonicStatus(copied ? 'Recovery phrase copied.' : 'Unable to copy the recovery phrase.', copied ? 'success' : 'error')
    }
    if (action === 'download-mnemonic') {
      if (!currentMnemonic) return
      downloadBlob('flamingo-wallet-recovery-phrase.txt', new Blob([currentMnemonic + '\n'], { type: 'text/plain;charset=utf-8' }))
      showMnemonicStatus('Recovery phrase saved.', 'success')
    }
    if (action === 'copy-node-id') {
      const copied = await copyText(currentNodeId)
      target.textContent = copied ? 'Copied' : 'Copy failed'
      window.setTimeout(function () { target.textContent = 'Copy node ID' }, 1600)
    }
  }

  function createWallet(button) {
    if (!shadow.querySelector('.create-confirmation').checked) return
    setButtonLoading(button, true, 'Creating wallet…')
    showStatus(shadow.querySelector('.create-status'), 'Stopping the current node and creating a new identity. This may take a few seconds…', 'info')
    request({ type: 'create_new_wallet' })
  }

  function receiveFromParent(message) {
    const data = message?.data || {}

    if (message?.type === 'wallet_setup_details_loaded') {
      const alias = shadow.querySelector('.current-wallet-alias')
      alias.textContent = data.status === 'success' && data.alias
        ? data.alias
        : (data.error || 'Wallet unavailable')
      alias.title = data.alias || ''
    }

    if (message?.type === 'wallet_scb_exported') {
      shadow.querySelectorAll('[data-action="download-scb"]').forEach(function (button) {
        setButtonLoading(button, false)
      })
      if (data.status !== 'success') {
        showStatus(scbStatusTarget, data.error || 'Unable to export the channel backup.', 'error')
        return
      }
      try {
        const bytes = hexToBytes(data.hex)
        downloadBlob(data.filename || 'emergency.recover', new Blob([bytes], { type: 'application/octet-stream' }))
        showStatus(scbStatusTarget, 'SCB backup downloaded successfully.', 'success')
      } catch (error) {
        showStatus(scbStatusTarget, error.message, 'error')
      }
    }

    if (message?.type === 'wallet_recovery_phrase_loaded') {
      if (walletCreated) return
      const help = shadow.querySelector('.mnemonic-help')
      if (data.status !== 'success' || !data.mnemonic) {
        help.textContent = data.error || 'The saved recovery phrase is unavailable for this wallet.'
        help.classList.add('status-text-error')
        return
      }
      currentMnemonic = data.mnemonic.trim()
      renderMnemonic()
      shadow.querySelectorAll('.mnemonic-action').forEach(function (button) { button.disabled = false })
      help.textContent = 'This is the recovery phrase saved for your current wallet. Save it before replacing the wallet.'
      help.classList.remove('status-text-error')
    }

    if (message?.type === 'new_wallet_created') {
      const createButton = shadow.querySelector('.create-button')
      setButtonLoading(createButton, false)
      if (data.status !== 'success' || !data.mnemonic || !data.nodeId) {
        showStatus(shadow.querySelector('.create-status'), data.error || 'The wallet could not be created.', 'error')
        return
      }

      currentMnemonic = data.mnemonic.trim()
      currentNodeId = data.nodeId
      walletCreated = true
      renderWalletDetails()
      shadow.querySelectorAll('.mnemonic-action').forEach(function (button) { button.disabled = false })
      shadow.querySelector('.created-node-card').classList.remove('hidden')
      shadow.querySelector('.create-confirmation').disabled = true
      createButton.textContent = 'Wallet created'
      createButton.disabled = true
      showStatus(shadow.querySelector('.create-status'), data.message || 'Wallet created successfully. Save your recovery phrase now.', 'success')
    }
  }

  function renderWalletDetails() {
    shadow.querySelectorAll('.node-id-value').forEach(function (node) { node.textContent = currentNodeId })
    renderMnemonic()
    const help = shadow.querySelector('.mnemonic-help')
    help.textContent = 'This is your new wallet recovery phrase. Store it offline and never share it.'
    help.classList.remove('status-text-error')
  }

  function renderMnemonic() {
    shadow.querySelectorAll('.mnemonic-text').forEach(function (field) {
      field.value = currentMnemonic
    })
  }

  function resetCreateView() {
    currentMnemonic = ''
    currentNodeId = ''
    walletCreated = false
    const confirmation = shadow.querySelector('.create-confirmation')
    confirmation.checked = false
    confirmation.disabled = false
    const createButton = shadow.querySelector('.create-button')
    createButton.textContent = 'Create new wallet'
    createButton.disabled = true
    delete createButton.dataset.originalLabel
    shadow.querySelector('.created-node-card').classList.add('hidden')
    shadow.querySelectorAll('.inline-status, .create-status').forEach(hideStatus)
    shadow.querySelectorAll('.mnemonic-action').forEach(function (button) { button.disabled = true })
    renderMnemonicPlaceholders()
  }

  function renderMnemonicPlaceholders() {
    shadow.querySelectorAll('.mnemonic-text').forEach(function (field) { field.value = '' })
    const help = shadow.querySelector('.mnemonic-help')
    help.textContent = 'Loading the recovery phrase saved for your current wallet…'
    help.classList.remove('status-text-error')
  }

  function showMnemonicStatus(message, type) {
    shadow.querySelectorAll('.copy-status, .create-copy-status').forEach(function (target) {
      showStatus(target, message, type)
    })
  }

  function showView(view) {
    shadow.querySelectorAll('[data-view]').forEach(function (section) {
      section.classList.toggle('hidden', section.dataset.view !== view)
    })
    shadow.querySelector('.wallet-setup').scrollTop = 0
  }

  function request(message) {
    if (typeof sendUp === 'function') sendUp({ from: 'wallet_setup', ...message })
  }

  function setButtonLoading(button, loading, label) {
    if (!button) return
    if (loading) {
      button.dataset.originalLabel = button.innerHTML
      button.textContent = label
      button.disabled = true
      button.classList.add('loading')
    } else {
      if (button.dataset.originalLabel) button.innerHTML = button.dataset.originalLabel
      button.disabled = button.classList.contains('create-button') && !shadow.querySelector('.create-confirmation').checked
      button.classList.remove('loading')
    }
  }

  function showStatus(target, message, type) {
    if (!target) return
    target.textContent = message
    target.className = target.className.replace(/\s(status-info|status-success|status-error)/g, '')
    target.classList.add(`status-${type}`)
    target.classList.remove('hidden')
  }

  function hideStatus(target) {
    target.classList.add('hidden')
    target.textContent = ''
  }

  function hexToBytes(hex) {
    if (!hex || hex.length % 2 !== 0 || !/^[0-9a-f]+$/i.test(hex)) throw new Error('The backend returned an invalid SCB file.')
    const bytes = new Uint8Array(hex.length / 2)
    for (let i = 0; i < hex.length; i += 2) bytes[i / 2] = parseInt(hex.slice(i, i + 2), 16)
    return bytes
  }

  function downloadBlob(filename, blob) {
    const url = window.URL.createObjectURL(blob)
    const anchor = document.createElement('a')
    anchor.href = url
    anchor.download = filename
    document.body.appendChild(anchor)
    anchor.click()
    anchor.remove()
    window.URL.revokeObjectURL(url)
  }

  async function copyText(text) {
    if (!text) return false
    try {
      if (navigator.clipboard?.writeText) {
        await navigator.clipboard.writeText(text)
      } else {
        const textarea = document.createElement('textarea')
        textarea.value = text
        document.body.appendChild(textarea)
        textarea.select()
        document.execCommand('copy')
        textarea.remove()
      }
      return true
    } catch (error) {
      return false
    }
  }

  async function onbatch(batch) {
    for (const { type, paths } of batch) {
      const data = await Promise.all(paths.map(function (path) {
        return drive.get(path).then(function (file) { return file.raw })
      }))
      const func = on[type] || fail
      await func(data, type)
    }
  }

  function inject(data) { style.textContent = data[0] }
  function ondata(data) { }
  function onicons(data) { }
  function fail(data, type) { throw new Error('invalid message', { cause: { data, type } }) }
}

function fallback_module() {
  return {
    api: fallback_instance,
    _: {
      'input_field': { $: '' },
      'button': { $: '' }
    }
  }

  function fallback_instance(opts) {
    if (!opts) opts = {}
    if (!opts.value) opts.value = {}

    return {
      drive: {
        'icons/': {
          'x.svg': { '$ref': 'x.svg' }
        },
        'style/': {
          'details_menu.css': { '$ref': 'details_menu.css' }
        },
        'data/': {
          'opts.json': { raw: opts || {} }
        }
      },
      _: {
        input_field: {
          mapping: { style: 'style', data: 'data', icons: 'icons' },
          0: {
            placeholder: '1BoatSLRHtKNngkdXEeobR76b53LETtpyT',
            address: '1BoatSLRHtKNngkdXEeobR76b53LETtpyT',
            icon: 'apple'
          }
        },
        button: {
          mapping: { style: 'style', data: 'data' },
          1: { label: 'Reveal' }
        }
      }
    }
  }
}
